  "cv.field.polishSummary": { ar: "ناجي يصوغ الملخص", en: "Naje drafts the summary", es: "Naje redacta el resumen", fr: "Naje rédige le résumé", de: "Naje formuliert die Zusammenfassung", pt: "O Naje redige o resumo" },
