  "cv.field.referencesHint": { ar: "«متوفرة عند الطلب» تكفي ما لم يُطلب غير ذلك.", en: "“Available on request” is enough unless asked otherwise.", es: "«Disponibles a petición» basta salvo que pidan otra cosa.", fr: "« Sur demande » suffit, sauf exigence contraire.", de: "„Auf Anfrage“ genügt, sofern nichts anderes verlangt wird.", pt: "«Disponíveis a pedido» chega, salvo pedido em contrário." },
  "cv.field.referencesPh": { ar: "متوفرة عند الطلب", en: "Available on request", es: "Disponibles a petición", fr: "Sur demande", de: "Auf Anfrage", pt: "Disponíveis a pedido" },
