  "cv.field.status": { ar: "الحالة", en: "Status", es: "Estado", fr: "Statut", de: "Status", pt: "Estado" },
  "cv.field.summary": { ar: "ملخص مهني", en: "Professional summary", es: "Resumen profesional", fr: "Résumé professionnel", de: "Berufliche Zusammenfassung", pt: "Resumo profissional" },
  "cv.field.summaryHint": { ar: "رقم واحد إن وُجد فعلاً. بلا «شغوف» أو «ديناميكي».", en: "One real number if you have it. No “passionate” or “dynamic”.", es: "Un número real si existe. Sin «apasionado» ni «dinámico».", fr: "Un vrai chiffre s’il existe. Pas de « passionné » ni « dynamique ».", de: "Eine echte Zahl, falls vorhanden. Kein „leidenschaftlich“ oder „dynamisch“.", pt: "Um número real se existir. Sem «apaixonado» nem «dinâmico»." },
  "cv.field.summaryPh": { ar: "مثال: محاسب تكاليف بخبرة 6 سنوات خفّض هدر المواد 14٪", en: "Example: a cost accountant with 6 years who cut material waste 14%", es: "Ejemplo: contable de costes con 6 años que redujo el desperdicio un 14 %", fr: "Exemple : un comptable de coûts, 6 ans, ayant réduit le gaspillage de 14 %", de: "Beispiel: Kostenbuchhalter, 6 Jahre, Materialverlust um 14 % gesenkt", pt: "Exemplo: contabilista de custos com 6 anos que reduziu o desperdício em 14%" },
  "cv.field.targetRole": { ar: "الوظيفة المستهدفة", en: "Target role", es: "Puesto objetivo", fr: "Poste visé", de: "Zielrolle", pt: "Função pretendida" },
  "cv.field.templateSearch": { ar: "ابحث في القوالب", en: "Search templates", es: "Buscar plantillas", fr: "Chercher un modèle", de: "Vorlagen suchen", pt: "Pesquisar modelos" },
  "cv.field.templateSearchPh": { ar: "ابحث بالاسم أو الوصف", en: "Search by name or description", es: "Busca por nombre o descripción", fr: "Recherche par nom ou description", de: "Nach Name oder Beschreibung suchen", pt: "Pesquisar por nome ou descrição" },
