  "cv.field.verifyUrl": { ar: "رابط التحقق", en: "Verification link", es: "Enlace de verificación", fr: "Lien de vérification", de: "Prüflink", pt: "Ligação de verificação" },
  "cv.field.visa": { ar: "حالة الإقامة / التأشيرة", en: "Residence or visa status", es: "Residencia o visado", fr: "Résidence ou visa", de: "Aufenthalt oder Visum", pt: "Residência ou visto" },
  "cv.field.visaHint": { ar: "سارية وقابلة للتحويل؟ زيارة؟ خارج الدولة؟", en: "Transferable and valid? A visit visa? Outside the country?", es: "¿Vigente y transferible? ¿Visita? ¿Fuera del país?", fr: "Valide et transférable ? Visite ? Hors du pays ?", de: "Gültig und übertragbar? Besuch? Außerhalb des Landes?", pt: "Válida e transferível? Visita? Fora do país?" },
  "cv.field.visaPh": { ar: "إقامة عمل قابلة للتحويل", en: "Transferable work residence", es: "Residencia de trabajo transferible", fr: "Résidence de travail transférable", de: "Übertragbarer Arbeitsaufenthalt", pt: "Residência de trabalho transferível" },
