  "cv.interview.confirm": { ar: "نعم، اكتبها", en: "Yes, write it", es: "Sí, escríbelo", fr: "Oui, écrivez-le", de: "Ja, schreiben", pt: "Sim, escreva" },
  "cv.interview.confirmKicker": { ar: "تأكيد", en: "Confirm", es: "Confirmar", fr: "Confirmer", de: "Bestätigen", pt: "Confirmar" },
  "cv.interview.correction": { ar: "تصحيح: {{text}}", en: "Correction: {{text}}", es: "Corrección: {{text}}", fr: "Correction : {{text}}", de: "Korrektur: {{text}}", pt: "Correção: {{text}}" },
  "cv.interview.defaultConfirm": { ar: "هذا ما سمعته. لا شيء يُكتب قبل تأكيدك.", en: "This is what I heard. Nothing is written until you confirm.", es: "Esto es lo que oí. Nada se escribe hasta que confirmes.", fr: "Voici ce que j’ai entendu. Rien n’est écrit avant votre confirmation.", de: "Das habe ich gehört. Nichts wird geschrieben, bevor Sie bestätigen.", pt: "Foi isto que ouvi. Nada é escrito até confirmar." },
  "cv.interview.done": { ar: "يكفي لمسودة أولى. يمكنك متابعة التحرير في الاستوديو.", en: "Enough for a first draft. You can keep editing in the studio.", es: "Basta para un primer borrador. Puedes seguir editando en el estudio.", fr: "Assez pour une première ébauche. Vous pouvez continuer dans l’atelier.", de: "Genug für einen ersten Entwurf. Sie können im Atelier weiterarbeiten.", pt: "Chega para um primeiro rascunho. Pode continuar a editar no estúdio." },
  "cv.interview.edit": { ar: "تعديل", en: "Edit", es: "Editar", fr: "Modifier", de: "Bearbeiten", pt: "Editar" },
  "cv.interview.enough": { ar: "يكفي", en: "I have enough", es: "Ya basta", fr: "C’est assez", de: "Das reicht", pt: "Já chega" },
  "cv.interview.err": { ar: "تعذّر المتابعة. أعد المحاولة.", en: "Could not continue. Try again.", es: "No se pudo continuar. Inténtalo de nuevo.", fr: "Impossible de continuer. Réessayez.", de: "Es ging nicht weiter. Versuchen Sie es erneut.", pt: "Não foi possível continuar. Tente de novo." },
  "cv.interview.failExtract": { ar: "لم أستطع تحويل ذلك إلى حقول. أعده بكلماتك.", en: "I could not turn that into fields. Say it again in your own words.", es: "No pude convertirlo en campos. Dilo otra vez con tus palabras.", fr: "Je n’ai pas pu en faire des champs. Redites-le avec vos mots.", de: "Daraus wurden keine Felder. Sagen Sie es noch einmal in Ihren Worten.", pt: "Não consegui transformar isso em campos. Diga-o outra vez com as suas palavras." },
  "cv.interview.firstQ": { ar: "ما اسمك الكامل، وما الدور الذي تستهدفه؟", en: "What is your full name, and which role are you aiming for?", es: "¿Cuál es tu nombre completo y a qué puesto apuntas?", fr: "Quel est votre nom complet, et quel poste visez-vous ?", de: "Wie lautet Ihr voller Name, und welche Rolle streben Sie an?", pt: "Qual é o seu nome completo e que função pretende?" },
  "cv.interview.kicker": { ar: "تحدث مع ناجي", en: "TALK TO NAJE", es: "HABLA CON NAJE", fr: "PARLER À NAJE", de: "MIT NAJE SPRECHEN", pt: "FALAR COM O NAJE" },
  "cv.interview.more": { ar: "زدني حقيقة واحدة.", en: "Tell me one more fact.", es: "Dime un hecho más.", fr: "Dites-moi un fait de plus.", de: "Nennen Sie noch eine Tatsache.", pt: "Diga mais um facto." },
  "cv.interview.notAdded": { ar: "تُرك خارج السيرة. يبقى في كلامك فقط.", en: "Left out of the CV. It stays in your words only.", es: "Quedó fuera del CV. Permanece solo en tus palabras.", fr: "Laissé hors du CV. Cela reste seulement dans vos mots.", de: "Nicht in den Lebenslauf übernommen. Es bleibt nur in Ihren Worten.", pt: "Ficou fora do CV. Permanece só nas suas palavras." },
  "cv.interview.ph": { ar: "إجابتك…", en: "Your answer…", es: "Tu respuesta…", fr: "Votre réponse…", de: "Ihre Antwort…", pt: "A sua resposta…" },
  "cv.interview.phPending": { ar: "أكّد السطر أعلاه أو صحّحه أولاً.", en: "Confirm or correct the line above first.", es: "Confirma o corrige primero la línea de arriba.", fr: "Confirmez ou corrigez d’abord la ligne ci-dessus.", de: "Bestätigen oder korrigieren Sie zuerst die Zeile oben.", pt: "Confirme ou corrija primeiro a linha acima." },
  "cv.interview.promise": { ar: "سؤال واحد في كل مرة. لا شيء يُكتب قبل تأكيدك. بلا وظائف أو أرقام مخترعة.", en: "One question at a time. Nothing is written until you confirm. No invented jobs or numbers.", es: "Una pregunta cada vez. Nada se escribe hasta que confirmes. Sin empleos ni cifras inventados.", fr: "Une question à la fois. Rien n’est écrit avant votre confirmation. Pas d’emplois ni de chiffres inventés.", de: "Eine Frage nach der anderen. Nichts wird geschrieben, bevor Sie bestätigen. Keine erfundenen Stellen oder Zahlen.", pt: "Uma pergunta de cada vez. Nada é escrito até confirmar. Sem empregos ou números inventados." },
  "cv.interview.reading": { ar: "ناجي يستمع…", en: "Naje is listening…", es: "Naje está escuchando…", fr: "Naje écoute…", de: "Naje hört zu…", pt: "O Naje está a ouvir…" },
  "cv.interview.reject": { ar: "لا تكتبها", en: "Don’t write it", es: "No lo escribas", fr: "Ne pas l’écrire", de: "Nicht schreiben", pt: "Não escrever" },
