  "cv.pack.hint": { ar: "خطاب، نبذة LinkedIn، ونبذة قصيرة — من حقائقك فقط. اللغة تتبع لغة الوثيقة لا الواجهة.", en: "A letter, a LinkedIn About, and a short bio — from your facts only. Language follows the document, not the interface.", es: "Carta, sección Acerca de de LinkedIn y una bio breve, solo con tus hechos. El idioma sigue al documento, no a la interfaz.", fr: "Lettre, section À propos LinkedIn et courte bio — uniquement vos faits. La langue suit le document, pas l’interface.", de: "Anschreiben, LinkedIn-Info und Kurzbio — nur aus Ihren Fakten. Die Sprache folgt dem Dokument, nicht der Oberfläche.", pt: "Carta, secção Sobre do LinkedIn e uma bio curta — só com os seus factos. O idioma segue o documento, não a interface." },
  "cv.pack.linkedin": { ar: "نبذة LinkedIn", en: "LinkedIn About", es: "Acerca de LinkedIn", fr: "À propos LinkedIn", de: "LinkedIn-Info", pt: "Sobre do LinkedIn" },
  "cv.pack.linkedinPh": { ar: "قسم «حول» كما في سجلك. بلا أرقام مخترعة.", en: "The About section, from your record. No invented metrics.", es: "La sección Acerca de, según tu historial. Sin cifras inventadas.", fr: "La section À propos, d’après votre dossier. Pas de chiffres inventés.", de: "Der Info-Text aus Ihrem Werdegang. Keine erfundenen Kennzahlen.", pt: "A secção Sobre, a partir do seu registo. Sem métricas inventadas." },
  "cv.pack.title": { ar: "حزمة التقديم", en: "Application pack", es: "Paquete de candidatura", fr: "Dossier de candidature", de: "Bewerbungsmappe", pt: "Dossier de candidatura" },
