  "cv.photo.enhance": { ar: "تحسين الاستوديو", en: "Studio grade", es: "Ajuste de estudio", fr: "Réglage d’atelier", de: "Atelier-Abstufung", pt: "Ajuste de estúdio" },
  "cv.photo.enhanced": { ar: "حُسّنت", en: "Graded", es: "Ajustada", fr: "Réglée", de: "Abgestuft", pt: "Ajustada" },
  "cv.photo.enhancing": { ar: "يُحسّن…", en: "Grading…", es: "Ajustando…", fr: "Réglage…", de: "Wird abgestuft…", pt: "A ajustar…" },
  "cv.photo.hint": { ar: "الصورة اختيارية. في أسواق القراءة الآلية يُفضَّل إخفاؤها. رأس وأكتاف، خلفية سادة، لباس رسمي.", en: "The photo is optional. Hide it for machine-reading markets. Head and shoulders, plain background, formal clothes.", es: "La foto es opcional. Ocúltala en mercados de lectura automática. Cabeza y hombros, fondo liso, ropa formal.", fr: "La photo est facultative. Masquez-la pour la lecture machine. Tête et épaules, fond uni, tenue formelle.", de: "Das Foto ist optional. Blenden Sie es für Maschinenlese-Märkte aus. Kopf und Schultern, schlichter Hintergrund, formelle Kleidung.", pt: "A foto é opcional. Oculte-a em mercados de leitura automática. Cabeça e ombros, fundo liso, roupa formal." },
  "cv.photo.hintCrop": { ar: "انقر على الوجه لتحريك القص.", en: "Click the face to move the crop.", es: "Haz clic en el rostro para mover el recorte.", fr: "Cliquez sur le visage pour déplacer le cadrage.", de: "Klicken Sie auf das Gesicht, um den Ausschnitt zu verschieben.", pt: "Clique no rosto para mover o recorte." },
  "cv.photo.light": { ar: "تحسين إضاءة — لا نغيّر ملامحك.", en: "A light grade — we do not change your features.", es: "Un ajuste de luz: no cambiamos tus rasgos.", fr: "Un réglage de lumière — nous ne changeons pas vos traits.", de: "Nur Lichtabstufung — wir ändern Ihre Gesichtszüge nicht.", pt: "Um ajuste de luz — não mudamos os seus traços." },
  "cv.photo.local": { ar: "تحسين محلي: تباين وإضاءة فقط — بلا تغيير ملامح.", en: "Local grade: contrast and light only — no change to your features.", es: "Ajuste local: solo contraste y luz, sin cambiar los rasgos.", fr: "Réglage local : contraste et lumière seulement — traits inchangés.", de: "Lokale Abstufung: nur Kontrast und Licht — Gesichtszüge bleiben.", pt: "Ajuste local: só contraste e luz — os traços não mudam." },
  "cv.photo.low": { ar: "الدقة منخفضة للطباعة. ارفع صورة أوضح (رأس وأكتاف).", en: "Resolution is low for print. Upload a clearer head-and-shoulders photo.", es: "La resolución es baja para imprimir. Sube una foto más nítida de cabeza y hombros.", fr: "La résolution est faible pour l’impression. Envoyez une photo plus nette, tête et épaules.", de: "Die Auflösung ist für den Druck zu niedrig. Laden Sie ein klareres Brustbild hoch.", pt: "A resolução é baixa para impressão. Envie uma foto mais nítida de cabeça e ombros." },
  "cv.photo.ready": { ar: "جاهزة", en: "Ready", es: "Lista", fr: "Prête", de: "Bereit", pt: "Pronta" },
  "cv.photo.remove": { ar: "حذف", en: "Remove", es: "Quitar", fr: "Retirer", de: "Entfernen", pt: "Remover" },
  "cv.photo.square": { ar: "أبعاد مربعة وصغيرة — غالباً سيلفي أو صورة جواز. استخدم رأس وأكتاف أوضح.", en: "Square and small — often a selfie or passport photo. Use a clearer head-and-shoulders shot.", es: "Cuadrada y pequeña: suele ser un selfi o un pasaporte. Usa cabeza y hombros más claros.", fr: "Carrée et petite — souvent un selfie ou un passeport. Préférez tête et épaules plus nets.", de: "Quadratisch und klein — oft ein Selfie oder Passfoto. Nutzen Sie ein klareres Brustbild.", pt: "Quadrada e pequena — muitas vezes uma selfie ou um passaporte. Use cabeça e ombros mais nítidos." },
  "cv.photo.title": { ar: "صورة مهنية", en: "Professional photo", es: "Foto profesional", fr: "Photo professionnelle", de: "Berufsfoto", pt: "Foto profissional" },
  "cv.photo.wide": { ar: "الصورة عريضة جداً — قد تكون لقطة أفقية أو جماعية. انقر على الوجه لقصّها رأسياً.", en: "The photo is very wide — it may be a landscape or a group shot. Click the face to crop it vertically.", es: "La foto es muy ancha: puede ser horizontal o de grupo. Haz clic en el rostro para recortarla en vertical.", fr: "La photo est très large — paysage ou groupe. Cliquez sur le visage pour un cadrage vertical.", de: "Das Foto ist sehr breit — vielleicht Querformat oder eine Gruppe. Klicken Sie auf das Gesicht für einen Hochformat-Ausschnitt.", pt: "A foto é muito larga — pode ser horizontal ou de grupo. Clique no rosto para a recortar na vertical." },
