  "cv.risk.reason.columns": { ar: "القوالب متعددة الأعمدة أو المزخرفة تُقرأ بترتيب خاطئ في كثير من الأنظمة.", en: "Multi-column or decorated templates are often read in the wrong order.", es: "Las plantillas de varias columnas o decoradas se leen a menudo en el orden equivocado.", fr: "Les modèles à plusieurs colonnes ou ornés sont souvent lus dans le mauvais ordre.", de: "Mehrspaltige oder verzierte Vorlagen werden oft in falscher Reihenfolge gelesen.", pt: "Modelos de várias colunas ou decorados são muitas vezes lidos na ordem errada." },
  "cv.risk.reason.dates": { ar: "تواريخ ناقصة تُربك ترتيب الخبرة.", en: "Missing dates scramble the order of experience.", es: "Fechas ausentes desordenan la experiencia.", fr: "Des dates manquantes brouillent l’ordre des expériences.", de: "Fehlende Daten bringen die Reihenfolge der Erfahrung durcheinander.", pt: "Datas em falta baralham a ordem da experiência." },
  "cv.risk.reason.headline": { ar: "بدون مسمّى واضح يفشل تصنيف الملف.", en: "Without a clear title the file is hard to classify.", es: "Sin un cargo claro el archivo es difícil de clasificar.", fr: "Sans titre clair, le fichier est difficile à classer.", de: "Ohne klaren Titel lässt sich die Datei schlecht einordnen.", pt: "Sem um cargo claro o ficheiro é difícil de classificar." },
  "cv.risk.reason.photo": { ar: "الصورة والعمر يعيقان التحليل الآلي وقد تُفقد بيانات التواصل إن وُضعت بجانبها.", en: "A photo and age hinder machine reading, and contact details beside them can be dropped.", es: "La foto y la edad estorban la lectura automática, y el contacto junto a ellas puede perderse.", fr: "La photo et l’âge gênent la lecture machine, et le contact placé à côté peut être perdu.", de: "Foto und Alter stören das Maschinenlesen, und Kontaktdaten daneben können verloren gehen.", pt: "A foto e a idade atrapalham a leitura automática, e o contacto ao lado pode perder-se." },
  "cv.scan.amber": { ar: "أصفر · ملخص عام أو تواريخ ناقصة", en: "Amber · generic summary or missing dates", es: "Ámbar · resumen genérico o fechas ausentes", fr: "Ambre · résumé générique ou dates manquantes", de: "Bernstein · allgemeiner Text oder fehlende Daten", pt: "Âmbar · resumo genérico ou datas em falta" },
