  "cv.studio.useMine": { ar: "ابدأ بسيرتي", en: "Start with mine", es: "Empezar con la mía", fr: "Commencer avec le mien", de: "Mit meinem beginnen", pt: "Começar com o meu" },
  "cv.studio.visualNote": { ar: "الوضع البصري للقوالب المزخرفة وللتسليم أمام إنسان، لا كضمان لمقابلة.", en: "Visual mode is for decorated templates handed to a person — not an interview guarantee.", es: "El modo visual es para plantillas decoradas ante una persona, no una garantía de entrevista.", fr: "Le mode visuel sert aux modèles ornés remis à une personne — pas une garantie d’entretien.", de: "Der visuelle Modus ist für gestaltete Vorlagen an einen Menschen — keine Interviewgarantie.", pt: "O modo visual é para modelos decorados entregues a uma pessoa — não uma garantia de entrevista." },
