  "cv.toast.profile": { ar: "نُسخ الاسم والتواصل من ملفك. راجعهما.", en: "Name and contact copied from your profile. Review them.", es: "Nombre y contacto copiados de tu perfil. Revísalos.", fr: "Nom et contact copiés depuis votre profil. Relisez-les.", de: "Name und Kontakt aus Ihrem Profil kopiert. Bitte prüfen.", pt: "Nome e contacto copiados do seu perfil. Reveja-os." },
  "cv.toast.skill": { ar: "أُضيفت «{{name}}» إلى المهارات. احذفها إن لم تكن لديك.", en: "Added “{{name}}” to skills. Remove it if you do not have it.", es: "Se añadió «{{name}}» a las competencias. Quítala si no la tienes.", fr: "« {{name}} » ajouté aux compétences. Retirez-le si vous ne l’avez pas.", de: "„{{name}}“ zu den Fähigkeiten hinzugefügt. Entfernen Sie es, wenn Sie es nicht können.", pt: "«{{name}}» foi adicionada às competências. Remova-a se não a tiver." },
  "cv.toast.summary": { ar: "أُعيدت صياغة الملخص من حقائقك.", en: "Summary rewritten from your facts.", es: "Resumen reescrito a partir de tus hechos.", fr: "Résumé réécrit à partir de vos faits.", de: "Zusammenfassung aus Ihren Fakten neu formuliert.", pt: "Resumo reescrito a partir dos seus factos." },
