function pick(locale: SupportedLocale): Record<string, string> {
  const out: Record<string, string> = {};
  for (const key of Object.keys(TABLE)) out[key] = TABLE[key][locale];
  return out;
}

export const cvPack: LocalePack = {
  ar: pick('ar'),
  en: pick('en'),
  es: pick('es'),
  fr: pick('fr'),
  de: pick('de'),
  pt: pick('pt'),
};
